// роль выпадающего списка роли (combobox + option). Уточнить при первом /qa-regress.
import { expect, Locator, Page } from '@playwright/test';
import { supabaseSession, SupabaseSession } from '../audit-log/audit-helpers';

export const TEST_COMPANY_ID = '4432bd2f-3f47-43cf-8ef2-b0c16436f025';
/** Диспетчер компании test (auth/dispatcher.json): имя в Team & Roles и в шапке. */
export const DISPATCHER_NAME = 'Test Nikita';
export const ROLE_DISPATCHER = 'Admin-dispatcher';
export const ROLE_OPS = 'Operations manager';

/** EN и компания «test» до загрузки страницы. */
export async function prepare(page: Page) {
  await page.addInitScript((company) => {
    try {
      window.localStorage.setItem('preferred-language', 'en');
      window.localStorage.setItem('selected-company-id', company);
    } catch { /* ignore */ }
  }, TEST_COMPANY_ID);
}

/** EN без выбора компании (гость). */
export async function prepareGuest(page: Page) {
  await page.addInitScript(() => {
    try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ }
  });
}

/** Строка участника на /Team (по имени или email). */
export function teamRow(page: Page, text: string | RegExp): Locator {
  return page.locator('tr, [role="row"]').filter({ hasText: text }).first();
}

/** /Team загружен (заголовок и кнопка приглашения видны). */
export async function openTeam(page: Page) {
  await page.goto('/Team');
  await expect(page.getByRole('button', { name: 'Invite a member' })).toBeVisible({ timeout: 30_000 });
}

/** Сменить роль участника в строке и дождаться тоста «Saved». */
export async function setMemberRole(page: Page, rowText: string | RegExp, role: string) {
  const row = teamRow(page, rowText);
  await expect(row, 'строка участника на /Team').toBeVisible({ timeout: 30_000 });
  const select = row.getByRole('combobox').first();
  await select.click();
  await page.getByRole('option', { name: role, exact: true }).click();
  await expect(select).toContainText(role);
  await expect(page.getByText('Saved', { exact: true }).first()).toBeVisible({ timeout: 15_000 });
}

/** Шапка: под именем пользователя написана роль. */
export async function expectHeaderRole(page: Page, name: string, role: string) {
  const box = page.getByText(name, { exact: true }).first().locator('xpath=..');
  await expect(box.getByText(role, { exact: true }), `в шапке «${name}» роль «${role}»`).toBeVisible({ timeout: 30_000 });
}

/** Открыть первый счёт компании и меню Actions. Возвращает id счёта. */
export async function openFirstInvoiceActions(page: Page): Promise<string> {
  await page.goto('/invoices');
  const numberBtn = page.getByRole('button', { name: /^INV-\d+$/ }).first();
  await expect(numberBtn, 'в компании test есть счёт (предусловие)').toBeVisible({ timeout: 30_000 });
  await numberBtn.click();
  await page.waitForURL(/\/InvoiceForm\?id=/i);
  const id = new URL(page.url()).searchParams.get('id') as string;
  await page.getByRole('button', { name: 'Actions' }).filter({ visible: true }).first().click();
  await expect(page.getByRole('menuitem').first()).toBeVisible();
  return id;
}

/** Заголовки прямого запроса от имени сессии. */
export function authHeaders(s: SupabaseSession) {
  return { apikey: s.apikey, Authorization: `Bearer ${s.token}`, Accept: 'application/json' };
}

export { supabaseSession };
